using System.Text.Json;using SupportAgent.Core.BusinessQuery;using SupportAgent.Core.ExternalData;using SupportAgent.Infrastructure.ExternalData;
namespace SupportAgent.Tests;
public class ExternalDataCompilerTests
{
 static readonly Guid Source=Guid.NewGuid();
 static ExternalEntityMapping Entity()=>new(){Id=Guid.NewGuid(),ExternalDataSourceId=Source,ExternalSchemaName="dbo",ExternalTableName="erp_sales_invoice",BusinessEntityName="SalesInvoices",IsEnabled=true,Fields=[F("doc_no","InvoiceNumber","String"),F("status","Status","String"),F("doc_date","InvoiceDate","Date"),F("net_total","TotalAmount","Money")]};
 static ExternalFieldMapping F(string physical,string logical,string type)=>new(){ExternalColumnName=physical,BusinessFieldName=logical,DisplayName=logical,DataType=type,IsQueryable=true};
 static BusinessSchema Schema()=>new([new("SalesInvoices","Sales invoices","",["invoice"],[new("InvoiceNumber","Invoice number","","String"),new("Status","Status","","String"),new("InvoiceDate","Invoice date","","Date"),new("TotalAmount","Total","","Money")])],[]);
 static BusinessQueryPlan Plan()=>new(){Entity="SalesInvoices",Select=["InvoiceNumber","TotalAmount"],Limit=25};
 [Fact]public void Compiler_generates_one_bounded_select_with_parameterized_malicious_value(){var p=Plan();p.Filters=[new("Status",BusinessQueryOperator.Equals,JsonSerializer.SerializeToElement("' OR 1=1 --"))];var q=new SqlServerBusinessQueryCompiler().Compile(p,Schema(),[Entity()],[]);Assert.StartsWith("SELECT TOP (26)",q.CommandText);Assert.DoesNotContain("' OR 1=1 --",q.CommandText);Assert.Equal("@p0",q.Parameters[0].Name);Assert.Equal("' OR 1=1 --",q.Parameters[0].Value);Assert.DoesNotContain(';',q.CommandText);}
 [Fact]public void Compiler_supports_sort_group_aggregation_date_range_and_null_checks(){var p=Plan();p.Select=[];p.GroupBy=["Status"];p.Aggregations=[new(BusinessAggregationFunction.Sum,"TotalAmount","Sales")];p.Filters=[new("InvoiceDate",BusinessQueryOperator.Between,JsonSerializer.SerializeToElement(new{start="2026-01-01",end="2026-12-31"})),new("Status",BusinessQueryOperator.IsNotNull,null)];p.Sort=[new("Sales",BusinessQuerySortDirection.Descending)];var q=new SqlServerBusinessQueryCompiler().Compile(p,Schema(),[Entity()],[]);Assert.Contains("SUM([t0].[net_total])",q.CommandText);Assert.Contains("GROUP BY [t0].[status]",q.CommandText);Assert.Contains("ORDER BY [Sales] DESC",q.CommandText);Assert.Equal(2,q.Parameters.Count);}
 [Theory][InlineData("dbo.AspNetUsers")][InlineData("PasswordHash")]public void Compiler_rejects_unapproved_identifiers(string field){var p=Plan();p.Select=[field];Assert.Throws<ExternalDataException>(()=>new SqlServerBusinessQueryCompiler().Compile(p,Schema(),[Entity()],[]));}
 [Fact]public void Sensitive_or_nonqueryable_fields_never_enter_logical_schema(){var e=Entity();e.Fields.Add(new(){ExternalColumnName="api_secret",BusinessFieldName="ApiSecret",DisplayName="Secret",DataType="String",IsQueryable=true,IsSensitive=true});var approved=e.Fields.Where(x=>x.IsQueryable&&!x.IsSensitive);Assert.DoesNotContain(approved,x=>x.BusinessFieldName=="ApiSecret");}
 [Fact]public void Compiler_unwraps_provider_typed_filter_values_without_trusting_type(){var p=Plan();p.Filters=[new("InvoiceDate",BusinessQueryOperator.GreaterThanOrEqual,JsonSerializer.SerializeToElement(new{type="DateTime",value="2026-09-01"})),new("Status",BusinessQueryOperator.Equals,JsonSerializer.SerializeToElement(new{type="String",value="Open"}))];var q=new SqlServerBusinessQueryCompiler().Compile(p,Schema(),[Entity()],[]);Assert.Equal("2026-09-01",q.Parameters[0].Value);Assert.Equal("Open",q.Parameters[1].Value);Assert.DoesNotContain("DateTime",q.Parameters.Select(x=>x.Value?.ToString()));}
}
